create table if not exists public.krim_country_operating_packs (
 id bigint generated by default as identity primary key,
 jurisdiction_code text not null unique check(jurisdiction_code ~ '^[A-Z]{2}$'),
 country_name text not null, pack_version integer not null default 1 check(pack_version>0),
 pack_status text not null default 'research_pending' check(pack_status in('research_pending','in_review','approved','suspended')),
 legal_owner text,next_review_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now()
);
create table if not exists public.krim_country_pack_controls (
 id bigint generated by default as identity primary key,
 pack_id bigint not null references public.krim_country_operating_packs(id) on delete restrict,
 control_code text not null,domain text not null,title text not null,service_scopes text[] not null default array['platform']::text[],
 mandatory boolean not null default true,applicability text not null default 'unknown' check(applicability in('yes','no','conditional','unknown')),
 review_status text not null default 'pending' check(review_status in('pending','in_review','approved','rejected','suspended')),
 source_id bigint references public.krim_market_regulatory_sources(id) on delete restrict,evidence_reference text,reviewer_note text,
 reviewed_by uuid,reviewed_at timestamptz,expires_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 unique(pack_id,control_code),check(expires_at is null or reviewed_at is null or expires_at>reviewed_at)
);
create table if not exists public.krim_country_pack_control_events (
 id bigint generated by default as identity primary key,control_id bigint not null references public.krim_country_pack_controls(id) on delete restrict,
 actor_user_id uuid,old_status text,new_status text not null,applicability text not null,rationale text not null,evidence_reference text,source_id bigint,created_at timestamptz not null default now()
);
alter table public.krim_country_operating_packs enable row level security;
alter table public.krim_country_operating_packs force row level security;
alter table public.krim_country_pack_controls enable row level security;
alter table public.krim_country_pack_controls force row level security;
alter table public.krim_country_pack_control_events enable row level security;
alter table public.krim_country_pack_control_events force row level security;
revoke all on public.krim_country_operating_packs,public.krim_country_pack_controls,public.krim_country_pack_control_events from anon,authenticated;
revoke all on sequence public.krim_country_operating_packs_id_seq,public.krim_country_pack_controls_id_seq,public.krim_country_pack_control_events_id_seq from anon,authenticated;
insert into public.krim_country_operating_packs(jurisdiction_code,country_name) select upper(code),name from public.krim_countries on conflict(jurisdiction_code) do nothing;
with d(control_code,domain,title,service_scopes) as (values
('ENTITY_PRESENCE','entity','Entity form, foreign ownership and local presence',array['platform','marketplace']::text[]),
('BUSINESS_LICENSING','licensing','Business and sector licensing boundaries',array['platform','road','rail','ocean','air','warehouse','customs']::text[]),
('TRANSPORT_MODES','transport','Mode-specific operator permits and safety requirements',array['road','rail','ocean','air','multimodal']::text[]),
('TAX_INVOICING','tax','Tax registrations, invoicing and statutory reporting',array['platform','marketplace','payments','finance']::text[]),
('PAYMENTS_FX','payments','Payment collection, custody, settlement and FX',array['payments','finance','marketplace']::text[]),
('CUSTOMS_TRADE','customs','Customs, import/export and trade controls',array['ocean','air','customs','freight_forwarding']::text[]),
('CARGO_ADMISSIBILITY','cargo','Restricted goods and dangerous-goods admissibility',array['road','rail','ocean','air','warehouse','customs']::text[]),
('PRIVACY_DATA','privacy','Privacy, data residency and international transfers',array['platform','all_workspaces','ai']::text[]),
('CONSUMER_MARKETPLACE','consumer','Consumer protection, marketplace disclosures and complaints',array['platform','marketplace','customer']::text[]),
('WORKFORCE_SAFETY','workforce','Employment, contractor and occupational safety',array['platform','road','rail','ocean','air','warehouse']::text[]),
('INSURANCE_LIABILITY','insurance','Compulsory insurance, cargo liability and claims',array['road','rail','ocean','air','warehouse','marketplace']::text[]),
('CONTRACTS_DISPUTES','contracts','Contract enforceability, signatures and dispute resolution',array['platform','marketplace','all_services']::text[]),
('COMPETITION_INTEGRITY','competition','Competition, anti-bribery and marketplace integrity',array['platform','marketplace','all_services']::text[]),
('CYBER_RESILIENCE','cybersecurity','Cybersecurity, incident reporting and continuity',array['platform','all_workspaces','ai']::text[]),
('ENVIRONMENT_FACILITIES','environment','Environmental, facility, fire and hazardous-storage controls',array['road','rail','ocean','air','warehouse']::text[]),
('LANGUAGE_ACCESSIBILITY','accessibility','Mandatory language, accessibility and record formats',array['platform','all_workspaces','customer']::text[]),
('LOCAL_OPERATIONS','operations','Local provider, facility, support and emergency readiness',array['all_services']::text[]),
('REGULATORY_MONITORING','regulatory_change','Official-source monitoring and regulatory change ownership',array['platform','all_services']::text[]))
insert into public.krim_country_pack_controls(pack_id,control_code,domain,title,service_scopes) select p.id,d.control_code,d.domain,d.title,d.service_scopes from public.krim_country_operating_packs p cross join d on conflict(pack_id,control_code) do nothing;
create or replace function public.krim_admin_list_country_packs() returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); r jsonb;
begin
 if u is null or coalesce(auth.jwt()->>'aal','')<>'aal2' or not private.krim_has_permission(u,1::bigint,'admin.platform') then raise exception using errcode='42501',message='AAL2 platform administrator access required'; end if;
 select coalesce(jsonb_agg(jsonb_build_object('pack_id',p.id,'jurisdiction_code',p.jurisdiction_code,'country_name',p.country_name,'pack_version',p.pack_version,'pack_status',p.pack_status,'legal_owner',p.legal_owner,'next_review_at',p.next_review_at,'controls',(select coalesce(jsonb_agg(jsonb_build_object('control_id',c.id,'control_code',c.control_code,'domain',c.domain,'title',c.title,'service_scopes',c.service_scopes,'mandatory',c.mandatory,'applicability',c.applicability,'review_status',c.review_status,'source_id',c.source_id,'evidence_reference',c.evidence_reference,'reviewer_note',c.reviewer_note,'reviewed_at',c.reviewed_at,'expires_at',c.expires_at) order by c.control_code),'[]'::jsonb) from public.krim_country_pack_controls c where c.pack_id=p.id)) order by p.country_name),'[]'::jsonb) into r from public.krim_country_operating_packs p;
 return jsonb_build_object('packs',r);
end $$;
create or replace function public.krim_admin_review_country_pack_control(p_control_id bigint,p_applicability text,p_review_status text,p_source_id bigint,p_evidence_reference text,p_reviewer_note text,p_expires_at timestamptz) returns jsonb language plpgsql security definer set search_path='' as $$
declare u uuid:=auth.uid(); c public.krim_country_pack_controls%rowtype; p public.krim_country_operating_packs%rowtype; s public.krim_market_regulatory_sources%rowtype;
begin
 if u is null or coalesce(auth.jwt()->>'aal','')<>'aal2' or not private.krim_has_permission(u,1::bigint,'admin.platform') then raise exception using errcode='42501',message='AAL2 platform administrator access required'; end if;
 if p_applicability not in('yes','no','conditional','unknown') or p_review_status not in('in_review','approved','rejected','suspended') then raise exception using errcode='22023',message='Invalid applicability or review status'; end if;
 select * into c from public.krim_country_pack_controls where id=p_control_id for update; if not found then raise exception using errcode='P0002',message='Country pack control not found'; end if;
 select * into p from public.krim_country_operating_packs where id=c.pack_id;
 if p_review_status='approved' then
  if p_applicability='unknown' or nullif(btrim(p_evidence_reference),'') is null or nullif(btrim(p_reviewer_note),'') is null or p_source_id is null then raise exception using errcode='22023',message='Approval requires resolved applicability, evidence, source and rationale'; end if;
  select * into s from public.krim_market_regulatory_sources where id=p_source_id;
  if not found or s.jurisdiction_code not in(p.jurisdiction_code,'*') or s.review_status not in('source_checked','legal_reviewed') then raise exception using errcode='22023',message='Source must be reviewed and match country'; end if;
  if c.domain in('entity','licensing','tax','payments','customs','privacy','consumer','workforce','insurance','contracts','competition') and not(s.source_kind in('qualified_legal_opinion','qualified_tax_opinion') and s.review_status='legal_reviewed') then raise exception using errcode='22023',message='This legal domain requires qualified legal or tax opinion'; end if;
  if p_expires_at is not null and p_expires_at<=now() then raise exception using errcode='22023',message='Expiry must be in future'; end if;
 end if;
 update public.krim_country_pack_controls set applicability=p_applicability,review_status=p_review_status,source_id=p_source_id,evidence_reference=nullif(btrim(p_evidence_reference),''),reviewer_note=nullif(btrim(p_reviewer_note),''),reviewed_by=u,reviewed_at=now(),expires_at=p_expires_at,updated_at=now() where id=p_control_id;
 insert into public.krim_country_pack_control_events(control_id,actor_user_id,old_status,new_status,applicability,rationale,evidence_reference,source_id) values(p_control_id,u,c.review_status,p_review_status,p_applicability,coalesce(nullif(btrim(p_reviewer_note),''),'Status changed'),nullif(btrim(p_evidence_reference),''),p_source_id);
 update public.krim_country_operating_packs set pack_status='in_review',updated_at=now() where id=p.id and pack_status='research_pending';
 return jsonb_build_object('success',true,'control_id',p_control_id,'review_status',p_review_status);
end $$;
create or replace function public.krim_internal_market_activation_gate(p_market_id bigint) returns jsonb language plpgsql security definer set search_path='' as $$
declare m public.krim_markets%rowtype; cid bigint; cc text; missing jsonb; miss_n integer; ass_n integer; cap_n integer; loc_n integer; src_n integer; exp_n integer; blockers jsonb; pack_id bigint; pack_status text; pc_expected integer; pc_approved integer;
begin
 select * into m from public.krim_markets where id=p_market_id; if not found then raise exception using errcode='P0002',message='Market not found'; end if;
 cid:=m.country_id; select upper(code) into cc from public.krim_countries where id=cid;
 select id,krim_country_operating_packs.pack_status into pack_id,pack_status from public.krim_country_operating_packs where jurisdiction_code=cc;
 select count(*) into pc_expected from public.krim_country_pack_controls where krim_country_pack_controls.pack_id=pack_id and mandatory;
 select count(*) into pc_approved from public.krim_country_pack_controls c join public.krim_market_regulatory_sources s on s.id=c.source_id where c.pack_id=pack_id and c.mandatory and c.review_status='approved' and c.applicability in('yes','no','conditional') and nullif(btrim(c.evidence_reference),'') is not null and nullif(btrim(c.reviewer_note),'') is not null and s.review_status in('source_checked','legal_reviewed') and (c.expires_at is null or c.expires_at>now());
 select count(*) into loc_n from public.krim_locations l where l.country_id=cid and l.is_active;
 select count(*) into cap_n from public.krim_partner_capabilities pc join public.krim_organizations o on o.id=pc.organization_id where pc.coverage_country_id=cid and pc.active and pc.verification_status='verified' and (pc.effective_from is null or pc.effective_from<=now()) and (pc.effective_until is null or pc.effective_until>now()) and o.status='active';
 select count(*) into exp_n from public.krim_market_readiness_requirements r where r.mandatory and r.jurisdiction_code in('*',upper(m.code));
 select count(*) into ass_n from public.krim_market_readiness_assessments a join public.krim_market_readiness_requirements r on r.id=a.requirement_id where a.market_id=p_market_id and r.mandatory and r.jurisdiction_code in('*',upper(m.code)) and a.status='approved' and nullif(btrim(a.evidence_reference),'') is not null and nullif(btrim(a.reviewer_note),'') is not null and (a.expires_at is null or a.expires_at>now());
 select count(*) into src_n from public.krim_market_readiness_requirements r where r.mandatory and r.jurisdiction_code in('*',upper(m.code)) and exists(select 1 from public.krim_market_regulatory_sources s where s.requirement_id=r.id and s.jurisdiction_code in('*',upper(m.code)) and s.review_status in('source_checked','legal_reviewed') and (r.category not in('legal_structure','licensing','tax','payments','privacy','consumer_protection','customs','trade_controls','transport_safety','workforce','insurance') or exists(select 1 from public.krim_market_regulatory_sources op where op.requirement_id=r.id and op.jurisdiction_code in('*',upper(m.code)) and op.source_kind in('qualified_legal_opinion','qualified_tax_opinion') and op.review_status='legal_reviewed' and nullif(btrim(op.evidence_reference),'') is not null)));
 select coalesce(jsonb_agg(jsonb_build_object('code',r.requirement_code,'category',r.category,'status',coalesce(a.status,'missing'),'evidence',a.evidence_reference,'expires_at',a.expires_at)),'[]'::jsonb) into missing from public.krim_market_readiness_requirements r left join public.krim_market_readiness_assessments a on a.requirement_id=r.id and a.market_id=p_market_id where r.mandatory and r.jurisdiction_code in('*',upper(m.code)) and (a.id is null or a.status<>'approved' or nullif(btrim(a.evidence_reference),'') is null or nullif(btrim(a.reviewer_note),'') is null or (a.expires_at is not null and a.expires_at<=now()));
 miss_n:=jsonb_array_length(missing);
 select coalesce(jsonb_agg(x),'[]'::jsonb) into blockers from (values
 (case when not(m.is_active and m.status='active') then 'Market catalogue is inactive' end),
 (case when loc_n=0 then 'No active service locations in this country' end),
 (case when cap_n=0 then 'No verified active partner capability in this country' end),
 (case when miss_n>0 then 'Mandatory market assessments missing, unapproved, unsupported or expired' end),
 (case when src_n<>exp_n then 'Mandatory market requirements lack reviewed sources or required qualified opinions' end),
 (case when pack_id is null then 'Country operating pack is missing' end),
 (case when pack_id is not null and (pack_status<>'approved' or pc_expected=0 or pc_approved<>pc_expected) then 'Country pack controls are incomplete, unapproved or expired' end)
 ) b(x) where x is not null;
 return jsonb_build_object('market_id',p_market_id,'market_code',m.code,'catalogue_active',m.is_active and m.status='active','country_pack_status',coalesce(pack_status,'missing'),'country_pack_controls_approved',pc_approved,'country_pack_controls_expected',pc_expected,'market_locations',loc_n,'verified_active_partner_capabilities',cap_n,'mandatory_assessments_approved',ass_n,'mandatory_requirements_expected',exp_n,'requirements_with_reviewed_sources',src_n,'missing_assessments',missing,'missing_assessment_count',miss_n,'eligible',(m.is_active and m.status='active' and loc_n>0 and cap_n>0 and miss_n=0 and src_n=exp_n and pack_id is not null and pack_status='approved' and pc_expected>0 and pc_approved=pc_expected),'blockers',blockers);
end $$;
revoke all on function public.krim_admin_list_country_packs() from public,anon;
revoke all on function public.krim_admin_review_country_pack_control(bigint,text,text,bigint,text,text,timestamptz) from public,anon;
grant execute on function public.krim_admin_list_country_packs() to authenticated;
grant execute on function public.krim_admin_review_country_pack_control(bigint,text,text,bigint,text,text,timestamptz) to authenticated;
